'use client';

import { Button, Card, Form, Input, message, Tabs, TabsProps } from 'antd';
import { useSettings } from '@/contexts/SettingsContext';
import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import PromptsTab from '@/components/PromptsTab';

const { Item } = Form;

export default function SettingsPage() {
  const [form] = Form.useForm();
  const { apiKey, apiUrl, model, setApiKey, setApiUrl, setModel, saveSettings } = useSettings();
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  useEffect(() => {
    form.setFieldsValue({
      apiKey,
      apiUrl,
      model,
    });
  }, [apiKey, apiUrl, model, form]);

  const handleSubmit = (values: {
    apiKey: string;
    apiUrl: string;
    model: string;
  }) => {
    try {
      setLoading(true);
      setApiKey(values.apiKey);
      setApiUrl(values.apiUrl);
      setModel(values.model);
      saveSettings();
      message.success('Settings saved successfully');
      router.push('/');
    } catch (error) {
      console.error('Failed to save settings:', error);
      message.error('Failed to save settings');
    } finally {
      setLoading(false);
    }
  };

  const items: TabsProps['items'] = [
    {
      key: '1',
      label: 'Basic',
      children: (
        <Form
          form={form}
          layout="vertical"
          onFinish={handleSubmit}
          initialValues={{
            apiKey,
            apiUrl,
            model,
          }}
        >
          <Item
            label="API Key"
            name="apiKey"
            rules={[
              { required: true, message: 'Please input your API key!' },
            ]}
          >
            <Input.Password placeholder="Enter your API key" />
          </Item>
          
          <Item
            label="API URL"
            name="apiUrl"
            rules={[
              { required: true, message: 'Please input the API URL!' },
              { type: 'url', message: 'Please enter a valid URL' },
            ]}
          >
            <Input placeholder="Enter API URL" />
          </Item>
          
          <Item
            label="Model"
            name="model"
            rules={[
              { required: true, message: 'Please input the model name!' },
            ]}
          >
            <Input placeholder="Enter model name" />
          </Item>
          
          <div className="flex justify-end gap-4">
            <Button onClick={() => router.back()}>
              Cancel
            </Button>
            <Button type="primary" htmlType="submit" loading={loading}>
              Save Settings
            </Button>
          </div>
        </Form>
      ),
    },
    {
      key: '2',
      label: 'Prompts',
      children: <PromptsTab />,
    },
  ];

  return (
    <div className="min-h-screen">
      <div className="max-w-5xl mx-auto p-6">
        <h1 className="text-3xl font-bold mb-8">Settings</h1>
        <Card>
          <Tabs defaultActiveKey="1" items={items} />
        </Card>
      </div>
    </div>
  );
}
