'use client';

import React, { createContext, useContext, ReactNode, useState, useEffect } from 'react';

export interface Prompt {
  id: string;
  name: string;
  content: string;
  isDefault: boolean;
  createdAt: number;
}

interface SettingsState {
  apiKey: string;
  apiUrl: string;
  model: string;
  prompts: Prompt[];
  selectedPromptId: string | null;
}

export interface SettingsContextType {
  apiKey: string;
  apiUrl: string;
  model: string;
  prompts: Prompt[];
  selectedPromptId: string | null;
  setApiKey: (key: string) => void;
  setApiUrl: (url: string) => void;
  setModel: (model: string) => void;
  addPrompt: (prompt: Omit<Prompt, 'id' | 'createdAt'>) => void;
  updatePrompt: (id: string, updates: Partial<Omit<Prompt, 'id'>>) => void;
  deletePrompt: (id: string) => void;
  setSelectedPrompt: (id: string | null) => void;
  saveSettings: () => void;
}

const defaultSettings = {
  apiKey: '',
  apiUrl: 'https://ark.cn-beijing.volces.com/api/v3/chat/completions',
  model: 'doubao-1.5-pro-256k-250115',
  prompts: [{
    id: 'default',
    name: 'Default Prompt',
    content: 'Generate test cases for the following requirements:',
    isDefault: true,
    createdAt: Date.now()
  }],
  selectedPromptId: 'default'
};

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

export const SettingsProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [settings, setSettings] = useState<SettingsState>(defaultSettings);
  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    const savedSettings = localStorage.getItem('openai-settings');
    if (savedSettings) {
      try {
        const parsedSettings = JSON.parse(savedSettings);
        // Merge with default settings but preserve prompts
        const { prompts, selectedPromptId, ...rest } = parsedSettings;
        setSettings({
          ...defaultSettings,
          ...rest,
          prompts: prompts || defaultSettings.prompts,
          selectedPromptId: selectedPromptId || defaultSettings.selectedPromptId
        });
      } catch (error) {
        console.error('Failed to parse saved settings', error);
      }
    }
    setIsInitialized(true);
  }, []);

  const saveSettings = () => {
    localStorage.setItem('openai-settings', JSON.stringify(settings));
  };

  if (!isInitialized) {
    return null;
  }

  const addPrompt = (prompt: Omit<Prompt, 'id' | 'createdAt'>) => {
    const newPrompt = {
      ...prompt,
      id: `prompt-${Date.now()}`,
      createdAt: Date.now()
    };
    
    setSettings(prev => {
      const updated = {
        ...prev,
        prompts: [...prev.prompts, newPrompt],
        selectedPromptId: newPrompt.id
      };
      localStorage.setItem('openai-settings', JSON.stringify(updated));
      return updated;
    });
  };

  const updatePrompt = (id: string, updates: Partial<Omit<Prompt, 'id'>>) => {
    setSettings(prev => {
      const updated = {
        ...prev,
        prompts: prev.prompts.map(prompt => 
          prompt.id === id ? { ...prompt, ...updates } : prompt
        )
      };
      localStorage.setItem('openai-settings', JSON.stringify(updated));
      return updated;
    });
  };

  const deletePrompt = (id: string) => {
    setSettings(prev => {
      const updatedPrompts = prev.prompts.filter(prompt => prompt.id !== id);
      const updatedSelectedId = prev.selectedPromptId === id ? 
        (updatedPrompts[0]?.id || null) : 
        prev.selectedPromptId;
      
      const updated = {
        ...prev,
        prompts: updatedPrompts,
        selectedPromptId: updatedSelectedId
      };
      
      localStorage.setItem('openai-settings', JSON.stringify(updated));
      return updated;
    });
  };

  const setSelectedPrompt = (id: string | null) => {
    setSettings(prev => {
      const updated = {
        ...prev,
        selectedPromptId: id
      };
      localStorage.setItem('openai-settings', JSON.stringify(updated));
      return updated;
    });
  };

  const contextValue: SettingsContextType = {
    apiKey: settings.apiKey,
    apiUrl: settings.apiUrl,
    model: settings.model,
    prompts: settings.prompts,
    selectedPromptId: settings.selectedPromptId,
    setApiKey: (key: string) => setSettings((prev) => ({ ...prev, apiKey: key })),
    setApiUrl: (url: string) => setSettings((prev) => ({ ...prev, apiUrl: url })),
    setModel: (model: string) => setSettings((prev) => ({ ...prev, model })),
    addPrompt,
    updatePrompt,
    deletePrompt,
    setSelectedPrompt,
    saveSettings,
  };

  return (
    <SettingsContext.Provider value={contextValue}>
      {children}
    </SettingsContext.Provider>
  );
};

export const useSettings = (): SettingsContextType => {
  const context = useContext(SettingsContext);
  if (context === undefined) {
    throw new Error('useSettings must be used within a SettingsProvider');
  }
  return context;
};
