'use client';

import { Button, Table, Space, Modal, Form, Input, Switch, message, Popconfirm } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined } from '@ant-design/icons';
import { useState } from 'react';
import { useSettings, Prompt } from '@/contexts/SettingsContext';

const { TextArea } = Input;

export default function PromptsTab() {
  const { prompts, addPrompt, updatePrompt, deletePrompt, selectedPromptId, setSelectedPrompt } = useSettings();
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [editingPrompt, setEditingPrompt] = useState<Prompt | null>(null);
  const [form] = Form.useForm();

  const handleAdd = () => {
    setEditingPrompt(null);
    form.resetFields();
    setIsModalVisible(true);
  };

  const handleEdit = (prompt: Prompt) => {
    setEditingPrompt(prompt);
    form.setFieldsValue({
      name: prompt.name,
      content: prompt.content,
      isDefault: prompt.isDefault
    });
    setIsModalVisible(true);
  };

  const handleDelete = (id: string) => {
    if (prompts.length <= 1) {
      message.error('Cannot delete the last prompt');
      return;
    }
    
    const prompt = prompts.find(p => p.id === id);
    if (prompt?.isDefault) {
      message.error('Cannot delete default prompt');
      return;
    }
    
    deletePrompt(id);
    message.success('Prompt deleted successfully');
  };

  const handleOk = async () => {
    try {
      const values = await form.validateFields();
      
      if (editingPrompt) {
        updatePrompt(editingPrompt.id, values);
        message.success('Prompt updated successfully');
      } else {
        addPrompt(values);
        message.success('Prompt added successfully');
      }
      
      setIsModalVisible(false);
    } catch (error) {
      console.error('Validation failed:', error);
    }
  };

  const handleCancel = () => {
    setIsModalVisible(false);
  };

  const handleSetDefault = (id: string) => {
    prompts.forEach(prompt => {
      if (prompt.id === id) {
        updatePrompt(prompt.id, { isDefault: true });
      } else if (prompt.isDefault) {
        updatePrompt(prompt.id, { isDefault: false });
      }
    });
  };

  const columns = [
    {
      title: 'Name',
      dataIndex: 'name',
      key: 'name',
    },
    {
      title: 'Content',
      dataIndex: 'content',
      key: 'content',
      render: (text: string) => (
        <div style={{ maxWidth: 400, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
          {text}
        </div>
      ),
    },
    {
      title: 'Default',
      dataIndex: 'isDefault',
      key: 'isDefault',
      width: 100,
      render: (isDefault: boolean, record: Prompt) => (
        <Switch 
          checked={isDefault} 
          onChange={() => handleSetDefault(record.id)}
        />
      ),
    },
    {
      title: 'Created At',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 200,
      render: (timestamp: number) => new Date(timestamp).toLocaleString(),
    },
    {
      title: 'Actions',
      key: 'actions',
      width: 150,
      render: ( record: Prompt) => (
        <Space size="middle">
          <Button 
            type="text" 
            icon={<EditOutlined />} 
            onClick={() => handleEdit(record)}
          />
          <Popconfirm
            title="Are you sure to delete this prompt?"
            onConfirm={() => handleDelete(record.id)}
            okText="Yes"
            cancelText="No"
            disabled={prompts.length <= 1 || record.isDefault}
          >
            <Button 
              type="text" 
              danger 
              icon={<DeleteOutlined />} 
              disabled={prompts.length <= 1 || record.isDefault}
            />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <div>
      <div style={{ marginBottom: 16 }}>
        <Button type="primary" onClick={handleAdd} icon={<PlusOutlined />}>
          Add Prompt
        </Button>
      </div>
      
      <Table 
        columns={columns} 
        dataSource={prompts} 
        rowKey="id"
        rowSelection={{
          type: 'radio',
          selectedRowKeys: selectedPromptId ? [selectedPromptId] : [],
          onChange: (selectedRowKeys) => {
            setSelectedPrompt(selectedRowKeys[0] as string);
          },
        }}
        pagination={false}
      />

      <Modal
        title={editingPrompt ? 'Edit Prompt' : 'Add New Prompt'}
        open={isModalVisible}
        onOk={handleOk}
        onCancel={handleCancel}
        width={700}
      >
        <Form
          form={form}
          layout="vertical"
          initialValues={{
            isDefault: false,
          }}
        >
          <Form.Item
            name="name"
            label="Name"
            rules={[{ required: true, message: 'Please input the prompt name!' }]}
          >
            <Input placeholder="Enter prompt name" />
          </Form.Item>
          
          <Form.Item
            name="content"
            label="Prompt Content"
            rules={[{ required: true, message: 'Please input the prompt content!' }]}
          >
            <TextArea rows={8} placeholder="Enter prompt content" />
          </Form.Item>
          
          <Form.Item
            name="isDefault"
            label="Set as default"
            valuePropName="checked"
          >
            <Switch />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
}
